import{_ as p,a0 as l,w as o,s as d,ao as h,I as n,x as s,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何在 Linux 中壓縮和解壓縮文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中壓縮和解壓縮文件 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中壓縮和解壓縮文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中壓縮和解壓縮文件 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180324 How To Compress And Decompress Files In Linux","title":"如何在 Linux 中壓縮和解壓縮文件","tag":"201809","desc":""},"relativePath":"201809/20180324 How To Compress And Decompress Files In Linux.md","filePath":"[post].md"}'),c={name:"201809/20180324 How To Compress And Decompress Files In Linux.md"};function g(r,i,k,b,u,x){const e=l("Link");return o(),d("div",null,[i[15]||(i[15]=h(`<h1 id="如何在-linux-中壓縮和解壓縮文件" tabindex="-1">如何在 Linux 中壓縮和解壓縮文件 <a class="header-anchor" href="#如何在-linux-中壓縮和解壓縮文件" aria-label="Permalink to “如何在 Linux 中壓縮和解壓縮文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/compress-720x340.jpg" alt=""></p><p>當在備份重要文件和通過網絡發送大文件的時候，對文件進行壓縮非常有用。請注意，壓縮一個已經壓縮過的文件會增加額外開銷，因此你將會得到一個更大一些的文件。所以，請不要壓縮已經壓縮過的文件。在 GNU/Linux 中，有許多程序可以用來壓縮和解壓縮文件。在這篇教程中，我們僅學習其中兩個應用程序。</p><p>在類 Unix 系統中，最常見的用來壓縮文件的程序是：</p><ol><li>gzip</li><li>bzip2</li></ol><h3 id="_1-使用-gzip-程序來壓縮和解壓縮文件" tabindex="-1">1. 使用 gzip 程序來壓縮和解壓縮文件 <a class="header-anchor" href="#_1-使用-gzip-程序來壓縮和解壓縮文件" aria-label="Permalink to “1. 使用 gzip 程序來壓縮和解壓縮文件”">​</a></h3><p><code>gzip</code> 是一個使用 Lempel-Ziv 編碼（LZ77）算法來壓縮和解壓縮文件的實用工具。</p><h4 id="_1-1-壓縮文件" tabindex="-1">1.1 壓縮文件 <a class="header-anchor" href="#_1-1-壓縮文件" aria-label="Permalink to “1.1 壓縮文件”">​</a></h4><p>如果要壓縮一個名為 <code>ostechnix.txt</code> 的文件，使之成為 gzip 格式的壓縮文件，那麼只需運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip ostechnix.txt</span></span></code></pre></div><p>上面的命令運行結束之後，將會出現一個名為 <code>ostechnix.txt.gz</code> 的 gzip 格式壓縮文件，代替了原始的 <code>ostechnix.txt</code> 文件。</p><p><code>gzip</code> 命令還可以有其他用法。一個有趣的例子是，我們可以將一個特定命令的輸出通過管道傳遞，然後作為 <code>gzip</code> 程序的輸入來創建一個壓縮文件。看下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l Downloads/ | gzip &gt; ostechnix.txt.gz</span></span></code></pre></div><p>上面的命令將會創建一個 gzip 格式的壓縮文件，文件的內容為 <code>Downloads</code>　目錄的目錄項。</p><h4 id="_1-2-壓縮文件並將輸出寫到新文件中-不覆蓋原始文件" tabindex="-1">1.2 壓縮文件並將輸出寫到新文件中（不覆蓋原始文件） <a class="header-anchor" href="#_1-2-壓縮文件並將輸出寫到新文件中-不覆蓋原始文件" aria-label="Permalink to “1.2 壓縮文件並將輸出寫到新文件中（不覆蓋原始文件）”">​</a></h4><p>默認情況下，<code>gzip</code> 程序會壓縮給定文件，並以壓縮文件替代原始文件。但是，你也可以保留原始文件，並將輸出寫到標準輸出。比如，下面這個命令將會壓縮 <code>ostechnix.txt</code> 文件，並將輸出寫入文件 <code>output.txt.gz</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -c ostechnix.txt &gt; output.txt.gz</span></span></code></pre></div><p>類似地，要解壓縮一個 <code>gzip</code> 格式的壓縮文件並指定輸出文件的文件名，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -c -d output.txt.gz &gt; ostechnix1.txt</span></span></code></pre></div><p>上面的命令將會解壓縮 <code>output.txt.gz</code> 文件，並將輸出寫入到文件 <code>ostechnix1.txt</code> 中。在上面兩個例子中，原始文件均不會被刪除。</p><h4 id="_1-3-解壓縮文件" tabindex="-1">1.3 解壓縮文件 <a class="header-anchor" href="#_1-3-解壓縮文件" aria-label="Permalink to “1.3 解壓縮文件”">​</a></h4><p>如果要解壓縮 <code>ostechnix.txt.gz</code> 文件，並以原始未壓縮版本的文件來代替它，那麼只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -d ostechnix.txt.gz</span></span></code></pre></div><p>我們也可以使用 <code>gunzip</code> 程序來解壓縮文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip ostechnix.txt.gz</span></span></code></pre></div><h4 id="_1-4-在不解壓縮的情況下查看壓縮文件的內容" tabindex="-1">1.4 在不解壓縮的情況下查看壓縮文件的內容 <a class="header-anchor" href="#_1-4-在不解壓縮的情況下查看壓縮文件的內容" aria-label="Permalink to “1.4 在不解壓縮的情況下查看壓縮文件的內容”">​</a></h4><p>如果你想在不解壓縮的情況下，使用 <code>gzip</code> 程序查看壓縮文件的內容，那麼可以像下面這樣使用 <code>-c</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip -c ostechnix1.txt.gz</span></span></code></pre></div><p>或者，你也可以像下面這樣使用 <code>zcat</code> 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zcat ostechnix.txt.gz</span></span></code></pre></div><p>你也可以通過管道將輸出傳遞給 <code>less</code> 命令，從而一頁一頁的來查看輸出，就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip -c ostechnix1.txt.gz | less</span></span>
<span class="line"><span>$ zcat ostechnix.txt.gz | less</span></span></code></pre></div><p>另外，<code>zless</code> 程序也能夠實現和上面的管道同樣的功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zless ostechnix1.txt.gz</span></span></code></pre></div><h4 id="_1-5-使用-gzip-壓縮文件並指定壓縮級別" tabindex="-1">1.5 使用 gzip 壓縮文件並指定壓縮級別 <a class="header-anchor" href="#_1-5-使用-gzip-壓縮文件並指定壓縮級別" aria-label="Permalink to “1.5 使用 gzip 壓縮文件並指定壓縮級別”">​</a></h4><p><code>gzip</code> 的另外一個顯著優點是支持壓縮級別。它支持下面給出的 3 個壓縮級別：</p><ul><li><strong>1</strong> – 最快 (最差)</li><li><strong>9</strong> – 最慢 (最好)</li><li><strong>6</strong> – 默認級別</li></ul><p>要壓縮名為 <code>ostechnix.txt</code> 的文件，使之成為“最好”壓縮級別的 gzip 壓縮文件，可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -9 ostechnix.txt</span></span></code></pre></div><h4 id="_1-6-連接多個壓縮文件" tabindex="-1">1.6 連接多個壓縮文件 <a class="header-anchor" href="#_1-6-連接多個壓縮文件" aria-label="Permalink to “1.6 連接多個壓縮文件”">​</a></h4><p>我們也可以把多個需要壓縮的文件壓縮到同一個文件中。如何實現呢？看下面這個例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -c ostechnix1.txt &gt; output.txt.gz</span></span>
<span class="line"><span>$ gzip -c ostechnix2.txt &gt;&gt; output.txt.gz</span></span></code></pre></div><p>上面的兩個命令將會壓縮文件 <code>ostechnix1.txt</code> 和 <code>ostechnix2.txt</code>，並將輸出保存到一個文件 <code>output.txt.gz</code> 中。</p><p>你可以通過下面其中任何一個命令，在不解壓縮的情況下，查看兩個文件 <code>ostechnix1.txt</code> 和 <code>ostechnix2.txt</code> 的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip -c output.txt.gz</span></span>
<span class="line"><span>$ gunzip -c output.txt</span></span>
<span class="line"><span>$ zcat output.txt.gz</span></span>
<span class="line"><span>$ zcat output.txt</span></span></code></pre></div><p>如果你想了解關於 <code>gzip</code> 的更多細節，請參閲它的 man 手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man gzip</span></span></code></pre></div><h3 id="_2-使用-bzip2-程序來壓縮和解壓縮文件" tabindex="-1">2. 使用 bzip2 程序來壓縮和解壓縮文件 <a class="header-anchor" href="#_2-使用-bzip2-程序來壓縮和解壓縮文件" aria-label="Permalink to “2. 使用 bzip2 程序來壓縮和解壓縮文件”">​</a></h3><p><code>bzip2</code> 和 <code>gzip</code> 非常類似，但是 <code>bzip2</code> 使用的是 Burrows-Wheeler 塊排序壓縮算法，並使用<ruby>哈夫曼<rt>Huffman</rt></ruby>編碼。使用 <code>bzip2</code> 壓縮的文件以 “.bz2” 擴展結尾。</p><p>正如我上面所説的， <code>bzip2</code> 的用法和 <code>gzip</code> 幾乎完全相同。只需在上面的例子中將 <code>gzip</code> 換成 <code>bzip2</code>，將 <code>gunzip</code> 換成 <code>bunzip2</code>，將 <code>zcat</code> 換成 <code>bzcat</code> 即可。</p><p>要使用 <code>bzip2</code> 壓縮一個文件，並以壓縮後的文件取而代之，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bzip2 ostechnix.txt</span></span></code></pre></div><p>如果你不想替換原始文件，那麼可以使用 <code>-c</code> 選項，並把輸出寫入到新文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bzip2 -c ostechnix.txt &gt; output.txt.bz2</span></span></code></pre></div><p>如果要解壓縮文件，則運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bzip2 -d ostechnix.txt.bz2</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bunzip2 ostechnix.txt.bz2</span></span></code></pre></div><p>如果要在不解壓縮的情況下查看一個壓縮文件的內容，則運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bunzip2 -c ostechnix.txt.bz2</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bzcat ostechnix.txt.bz2</span></span></code></pre></div><p>如果你想了解關於 <code>bzip2</code> 的更多細節，請參閲它的 man 手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man bzip2</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇教程中，我們學習了 <code>gzip</code> 和 <code>bzip2</code> 程序是什麼，並通過 GNU/Linux 下的一些例子學習瞭如何使用它們來壓縮和解壓縮文件。接下來，我們將要學習如何在 Linux 中將文件和目錄歸檔。</p><p>乾杯！</p><hr>`,68)),n("p",null,[i[1]||(i[1]=s("via: ",-1)),t(e,{href:"https://www.ostechnix.com/how-to-compress-and-decompress-files-in-linux/"},{default:a(()=>[...i[0]||(i[0]=[s("https://www.ostechnix.com/how-to-compress-and-decompress-files-in-linux/",-1)])]),_:1})]),n("p",null,[i[6]||(i[6]=s("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...i[2]||(i[2]=[s("SK",-1)])]),_:1}),i[7]||(i[7]=s(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[3]||(i[3]=[s("lujun9972",-1)])]),_:1}),i[8]||(i[8]=s(" 譯者：",-1)),t(e,{href:"https://github.com/ucasFL"},{default:a(()=>[...i[4]||(i[4]=[s("ucasFL",-1)])]),_:1}),i[9]||(i[9]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[5]||(i[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[12]||(i[12]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[10]||(i[10]=[s("LCTT",-1)])]),_:1}),i[13]||(i[13]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...i[11]||(i[11]=[s("Linux中國",-1)])]),_:1}),i[14]||(i[14]=s(" 榮譽推出",-1))])])}const y=p(c,[["render",g]]);export{m as __pageData,y as default};
